   372                                  const start = new Date(window.start);
   373                                  const end = new Date(window.end);
   374                                  const now = new Date();
   375                                  const repeatInterval = window.repeat || 0;
   376
   377                                  // If start is < now and end > now, we're in maintenance
   378                                  if (start <= now && end >= now) return true;
   379
   380                                  // If maintenance window was set in the past with a repeat,
   381                                  // we need to advance start and end to see if we are in range
