   383                                  while (start < now && repeatInterval !== 0) {
   384                                          start.setTime(start.getTime() + repeatInterval);
   385                                          end.setTime(end.getTime() + repeatInterval);
   386                                          if (start <= now && end >= now) {
   387                                                  return true;
