   431          private evaluateMonitorAction(statusChangeResult: StatusChangeResult): MonitorActionDecision {
   432                  const { monitor, statusChanged, prevStatus } = statusChangeResult;
   433
   434                  // Initialize result
   435                  const decision: MonitorActionDecision = {
   436                          shouldCreateIncident: false,
   437                          shouldResolveIncident: false,
   438                          shouldSendNotification: false,
   439                          incidentReason: null,
   440                          notificationReason: null,
   441                  };
   442
   443                  if (!statusChanged) {
   444                          return decision;
   445                  }
   446
   447                  if (monitor.status === "down") {
   448                          // Monitor went down (unreachable)
   449                          decision.shouldCreateIncident = true;
   450                          decision.shouldSendNotification = true;
   451                          decision.incidentReason = "status_down";
   452                          decision.notificationReason = "status_change";
   453                  } else if (monitor.status === "breached") {
   454                          // Hardware monitor exceeded thresholds
   455                          decision.shouldCreateIncident = true;
   456                          decision.shouldSendNotification = true;
   457                          decision.incidentReason = "threshold_breach";
   458                          decision.notificationReason = "threshold_breach";
   459                  } else if (monitor.status === "up" && (prevStatus === "down" || prevStatus === "breached")) {
   460                          // Monitor recovered from down or breached state
   461                          decision.shouldResolveIncident = true;
   462                          decision.shouldSendNotification = true;
   463                          decision.notificationReason = "status_change";
   464                  }
