   470                  if (!monitor.escalationPolicy || monitor.escalationPolicy.length === 0) {
   471                          return;
   472                  }
   473
   474                  const activeIncident = await this.incidentsRepository.findActiveByMonitorId(monitor.id, monitor.teamId);
   475                  if (!activeIncident) {
   476                          return;
   477                  }
   478
   479                  // Rollout guard: only incidents created after escalation support was introduced.
   480                  if (activeIncident.escalationVersion !== 1) {
   481                          return;
   482                  }
   483
   484                  const elapsedMinutes = this.getElapsedMinutes(activeIncident.startTime);
   485                  const alreadyNotified = new Set(activeIncident.escalationNotifiedMinutes ?? []);
   486                  const pendingMilestones = monitor.escalationPolicy
   487                          .map((step) => step.delayMinutes)
   488                          .filter((delayMinutes) => delayMinutes <= elapsedMinutes && !alreadyNotified.has(delayMinutes))
   489                          .sort((a, b) => a - b);
   490
   491                  for (const delayMinutes of pendingMilestones) {
   492                          const marked = await this.incidentsRepository.markEscalationNotified(activeIncident.id, activeIncident.teamId, delayMinutes);
   493                          if (!marked) {
   494                                  continue;
   495                          }
   496
   497                          await this.notificationsService.handleEscalationNotification(monitor, status, activeIncident, delayMinutes);
   498                  }
   499          }
