   501          private getElapsedMinutes(startTime: string): number {
   502                  const start = new Date(startTime);
   503                  if (Number.isNaN(start.getTime())) {
   504                          return 0;
   505                  }
   506
   507                  return Math.max(0, Math.floor((Date.now() - start.getTime()) / 60000));
   508          }
